#!/usr/bin/env bash
# Companion feed: the plugin's own HTTP listener and the page it serves. No device.
#   vst/tests/companion.sh
# Three runs: the listener on a test port (all endpoint checks), DJF2_HTTP=0 proving the switch
# closes the socket, and DJF2_HTTP_RW=0 proving a read-only device refuses writes.
# Needs build/params.h (generated by vst/test.sh's first stage); the C engine is compiled with
# gcc and linked with the C++ server through g++, because the engine is C and the server is not.
set -euo pipefail
HERE="$(cd "$(dirname "$0")/.." && pwd)"   # .../vst
# The Docker daemon runs on the host and only sees host-visible paths: set
# MPC_VST_HOST_ROOT to how it sees this repo (empty when docker runs here).
WS="${MPC_VST_WORKSPACE:-$(git -C "$HERE" rev-parse --show-toplevel 2>/dev/null || echo "")}"
HOST_ROOT="${MPC_VST_HOST_ROOT:-}"
host() { case "$1" in
  "$WS")   printf '%s' "${HOST_ROOT:-$WS}" ;;
  "$WS"/*) printf '%s%s' "$HOST_ROOT" "${1#"$WS"}" ;;
  *)       printf '%s' "$1" ;;
esac; }

PORT="${DJF2_TEST_PORT:-18102}"
OFF_PORT=$((PORT + 1))
RO_PORT=$((PORT + 2))

# The page is generated into a .so string: a stale header would serve an old panel.
python3 "$HERE/web/embed.py" --check || exit 1

docker run --rm -e "DJF2_HTTP_PORT=$PORT" \
  -v "$(host "$WS")":/w -w "/w${HERE#"$WS"}" gcc:12 bash -lc '
set -e
[ -f build/params.h ] || { echo "FAIL: build/params.h is missing — run vst/test.sh first"; exit 1; }
INC="-I. -Iinclude -I/w/mpc-vst-plugins/wrapper -Ibuild"
rm -rf /tmp/obj; mkdir -p /tmp/obj
for f in src/djfx_engine.c src/iso.c src/dub_delay.c src/dub_filter.c src/dub_reverb.c \
         src/repeat.c src/flanger.c src/grain.c src/limiter.c; do
  gcc -c -O2 -std=gnu11 $INC "$f" -o "/tmp/obj/$(basename "$f" .c).o"
done
g++ -std=gnu++17 -O2 -Wall -Wextra $INC -o /tmp/djfx_test \
  tests/companion_test.cpp src/dsp/companion.cpp src/dsp/qrcodegen.c /tmp/obj/*.o \
  -lm -lpthread 2>&1 | grep -E "error|Error" && exit 1 || true
/tmp/djfx_test

# The switch: with DJF2_HTTP=0 nothing may listen, even though an instance exists.
DJF2_HTTP=0 DJF2_HTTP_PORT=$DJF2_HTTP_PORT /tmp/djfx_test --instance-only >/dev/null 2>&1 &
pid=$!
sleep 0.5
# --probe exits 0 when the port is CLOSED (that is the pass for this run), 3 when open.
if /tmp/djfx_test --probe $DJF2_HTTP_PORT; then
  echo "PASS: DJF2_HTTP=0 opens no listener"
else
  echo "FAIL: DJF2_HTTP=0 still opened a listener"
  kill $pid 2>/dev/null || true
  exit 1
fi
kill $pid 2>/dev/null || true; wait $pid 2>/dev/null || true

# The read-only switch: page and /state stay, writes are refused.
DJF2_HTTP_RW=0 DJF2_HTTP_PORT=$((DJF2_HTTP_PORT + 2)) /tmp/djfx_test --rw-off $((DJF2_HTTP_PORT + 2))
'
